// Parse a bounded token as an integer, keeping its absolute value.  The VCF
// specification uses '.' (and ':' in some per-allele lists) as missing value
// sentinels; anything else that is not a plain integer is treated the same.
// Returns 1 when the token holds a usable number.
static int parse_ll_abs(const char *p, const char *q, long long *v)
{
    const char *t = p;
    long long x = 0;
    if (t == q || *t == '.' || *t == ':') return 0;
    if (*t == '+' || *t == '-') ++t;
    if (t == q) return 0;
    for (; t < q; ++t) {
        if (*t < '0' || *t > '9') return 0;
        x = x < LLONG_MAX / 10 ? x * 10 + (*t - '0') : LLONG_MAX / 2;
    }
    *v = x;
    return 1;
}

// Extend the reference interval of a VCF record using its SVLEN INFO values.
// Per the VCF specification (see the definitions of INFO/END and INFO/SVLEN),
// the end position of DEL/DUP/INV/CNV symbolic structural variant alleles is
// POS+|SVLEN| while all other alleles (including <INS>) end with the last
// REF base.  This computes the footprint of records carrying no usable
// INFO/END value.  SVLEN values (Number=A) are matched in order against the
// ALT alleles in [line+alt_b, line+alt_i).
static void vcf_svlen_extend_end(tbx_intv_t *intv, const char *line,
                                 size_t alt_b, size_t alt_i, const char *values)
{
    const char *ap = line + alt_b;          /* start of current ALT allele */
    const char *const aend = line + alt_i;  /* end of the ALT column */
    const char *vp = values;                /* start of current SVLEN value */
    for (;;) {
        const char *an = memchr(ap, ',', aend - ap);
        const char *vn;
        size_t an_len;
        if (!an) an = aend;
        an_len = an - ap;
        vn = strchr(vp, ',');   /* values come from a NUL-terminated column */
        if (!vn) vn = vp + strlen(vp);
        if ((an_len == 5 || (an_len > 5 && ap[4] == ':'))
            && ap[0] == '<' && ap[an_len-1] == '>'
            && (memcmp(ap+1, "DEL", 3) == 0 || memcmp(ap+1, "DUP", 3) == 0
                || memcmp(ap+1, "INV", 3) == 0 || memcmp(ap+1, "CNV", 3) == 0)) {
            long long v;
            if (parse_ll_abs(vp, vn, &v)) {
                hts_pos_t cand = v > HTS_POS_MAX - intv->beg - 1
                    ? HTS_POS_MAX : intv->beg + 1 + v;
                if (cand > intv->end) intv->end = cand;
            }
        }
        if (*vn == '\0' || an == aend) break;  /* either list is exhausted */
        vp = vn + 1;
        ap = an + 1;
    }
}

